USE enlazate;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(24) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NULL, customer_name VARCHAR(190) NOT NULL, business_name VARCHAR(190) NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(190) NULL, delivery_address VARCHAR(255) NULL, notes TEXT NULL, currency CHAR(3) NOT NULL DEFAULT 'DOP', subtotal_dop DECIMAL(12,2) NOT NULL DEFAULT 0, shipping_dop DECIMAL(12,2) NOT NULL DEFAULT 0, discount_dop DECIMAL(12,2) NOT NULL DEFAULT 0, total_dop DECIMAL(12,2) NOT NULL DEFAULT 0, payment_method ENUM('pending','manual_transfer','cash','provider') NOT NULL DEFAULT 'pending', payment_status ENUM('pending','partial','paid','failed') NOT NULL DEFAULT 'pending', status ENUM('new','pending_confirmation','confirmed','pending_payment','paid','preparing','sent_to_supplier','in_production','received','ready','delivered','cancelled') NOT NULL DEFAULT 'new', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, INDEX idx_orders_status(status), INDEX idx_orders_created(created_at));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NULL, product_name VARCHAR(190) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price_dop DECIMAL(12,2) NOT NULL, options JSON NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL, changed_by BIGINT UNSIGNED NULL, note TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(changed_by) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method VARCHAR(40) NOT NULL, amount_dop DECIMAL(12,2) NOT NULL, reference VARCHAR(120) NULL, status ENUM('pending','confirmed','rejected') NOT NULL DEFAULT 'pending', paid_at DATETIME NULL, notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
